package io.github.igorcv88.oneuiliquidglass.ui;

import android.content.Context;
import io.github.igorcv88.oneuiliquidglass.R;
import io.github.igorcv88.oneuiliquidglass.config.Controls;

/** Generated by tools/generate-control-reasons.py. */
final class ControlReasons {
    static String text(Context context, String reason) {
        if (reason == null || reason.isEmpty()) return reason;
        switch (reason) {
            case "A central não usa lente": return context.getString(R.string.control_reason_e07dc8a3703f);
            case "Aplicado ao reiniciar o userspace": return context.getString(R.string.control_reason_d4bd84227eae);
            case "Ative Central de controle": return context.getString(R.string.control_reason_a3e7e0b76d4e);
            case "Ative Discos adaptativos no fundo claro": return context.getString(R.string.control_reason_c7b014969049);
            case "Ative Personalizar discos no fundo colorido": return context.getString(R.string.control_reason_1a7887363bcf);
            case "Ative a faixa de lente no pop-up": return context.getString(R.string.control_reason_68b4e7a148ca);
            case "Ative o contraste medido no pop-up": return context.getString(R.string.control_reason_0bb90a8a05fd);
            case "Ative o desfoque próprio por cartão": return context.getString(R.string.control_reason_f9fe4db0d83c);
            case "Ative o texto adaptativo": return context.getString(R.string.control_reason_d39cd5584b3f);
            case "Ative o vidro no resumo de ícones": return context.getString(R.string.control_reason_4feba1d07807);
            case "Com o material do pop-up, vale a refração do pop-up": return context.getString(R.string.control_reason_72a5beb4b605);
            case "Desative Discos desligados sem fundo": return context.getString(R.string.control_reason_37d1bfc3168b);
            case "Estado lido do aparelho": return context.getString(R.string.control_reason_e061dd5d8ae0);
            case "Exige o desfoque desenhado no cartão": return context.getString(R.string.control_reason_17236c820833);
            case "Exige saturação, escurecimento ou clareamento": return context.getString(R.string.control_reason_7bc5b40329fd);
            case "Legado sem efeito visual": return context.getString(R.string.control_reason_79d513d51655);
            case "O vidro está desligado": return context.getString(R.string.control_reason_61e39f9c26d3);
            case "O vidro está desligado onde este ajuste vale": return context.getString(R.string.control_reason_317c7653bd1b);
            case "Sem efeito na proteção Adaptativa": return context.getString(R.string.control_reason_b7d2e9ae3d5f);
            case "Sem efeito no vidro padrão": return context.getString(R.string.control_reason_65e66e7ee1c0);
            case "Só funciona com o menisco desligado": return context.getString(R.string.control_reason_9c1dfe250b2b);
            case "Só funciona com o véu acima de 0": return context.getString(R.string.control_reason_a68b50de9042);
            case "Usado com a lente dinâmica": return context.getString(R.string.control_reason_d819d244b0d8);
            case "Usado com o modelo Física": return context.getString(R.string.control_reason_d390f2b8bbe0);
            case "Usado com o modelo Lente suave": return context.getString(R.string.control_reason_02be17ba5336);
            case "Usado com o vidro Fosco": return context.getString(R.string.control_reason_f4f63ea644e0);
            case "Usado com o vidro Transparente": return context.getString(R.string.control_reason_bd5401253fcd);
            case "Usado no modo de captura": return context.getString(R.string.control_reason_f27398911a67);
            case "Usado no vidro padrão": return context.getString(R.string.control_reason_7d2a689e3b24);
            case "Usado no vidro padrão com a faixa de lente": return context.getString(R.string.control_reason_f3bf628a079b);
            case "Usado no vidro padrão ou com a lente dinâmica": return context.getString(R.string.control_reason_01bce8dcfea3);
            case "Usado no vidro padrão ou na captura": return context.getString(R.string.control_reason_67e88d51c693);
            case "Use a proteção Adaptativa": return context.getString(R.string.control_reason_75fc35286ab7);
            case "Use o mapa de tons da lente na central": return context.getString(R.string.control_reason_3184fcb1d60f);
            case "Use o véu fixo ou o mapa de tons da lente": return context.getString(R.string.control_reason_1ab80b407e46);
            default: break;
        }
        for (Controls.Surface surface : Controls.Surface.values()) {
            if (reason.equals("O vidro está desligado em " + surface.label))
                return context.getString(R.string.control_surface_off, HomePage.surfaceLabel(context, surface));
            for (java.util.Map.Entry<String, String> layer : Controls.layers(surface).entrySet())
                if (reason.equals("A camada " + layer.getValue() + " está desligada"))
                    return context.getString(R.string.control_layer_off, UiLabels.layer(context, layer.getKey()));
        }
        return reason;
    }
    private ControlReasons() {}
}
